 const submitAction=async(event:FormEvent)=>{event.preventDefault();if(!action||busy)return;const entity=action.kind==='order'?snapshot.orders.find(item=>item.id===action.id):action.kind==='lot'?snapshot.lots.find(item=>item.id===action.id):snapshot.tasks.find(item=>item.id===action.id);if(!entity)return;const note=actionValues.note.trim();if(['cancel','block','rework','complete','verify','reopen','assign'].includes(action.action)&&note.length<10){setActionError(w('دلیل یا گزارش اقدام حداقل ۱۰ نویسه لازم دارد.','Reason or action report requires at least 10 characters.','السبب أو تقرير الإجراء يتطلب ١٠ محارف على الأقل.','Gerekçe veya işlem raporu en az 10 karakter gerektirir.'));return;}if(action.action==='finish'&&(!actionValues.good||!actionValues.scrap||reconciliation!==0||[Number(actionValues.good),Number(actionValues.scrap)].some(n=>!Number.isSafeInteger(n)||n<0))){setActionError(w('تعداد سالم و ضایعات باید صحیح و نامنفی باشند و جمع آن‌ها با تعداد بچ برابر باشد.','Good and scrap counts must be nonnegative integers and sum to batch quantity.','السليم والهدر أعداد صحيحة غير سالبة ومجموعهما يساوي كمية الدفعة.','Sağlam ve fire sayıları negatif olmayan tam sayı olmalı ve toplamları parti miktarına eşit olmalı.'));return;}if(action.kind==='lot'&&action.action==='release'&&!actionValues.inspectionId){setActionError(w('بازرسی تأییدشده همان بچ و محصول را انتخاب کنید.','Select an approved inspection for this batch and product.','اختر فحصاً معتمداً للدفعة والمنتج نفسيهما.','Aynı parti ve ürün için onaylı kontrol seçin.'));return;}const body:any={version:entity.version,action:action.action,note};if(action.action==='finish'){body.good=Number(actionValues.good);body.scrap=Number(actionValues.scrap);}if(action.kind==='lot'&&action.action==='release')body.inspectionId=actionValues.inspectionId;if(action.action==='assign'){if(!actionValues.ownerId||!actionValues.dueDate){setActionError(w('مسئول جدید و موعد را انتخاب کنید.','Select the new owner and due date.','اختر المسؤول الجديد والموعد.','Yeni sorumlu ve vade seçin.'));return;}body.ownerId=actionValues.ownerId;body.dueDate=actionValues.dueDate;}setBusy(true);setActionError('');setSuccess('');try{await api(`/operations/${action.kind==='order'?'orders':action.kind==='lot'?'lots':'tasks'}/${action.id}`,'PATCH',body);if(!alive.current)return;setAction(null);await load();await onChanged?.().catch(error=>{if(alive.current)setLoadError(visibleError(error));});setSuccess(w('اقدام ثبت شد و وضعیت از سرور دریافت شد.','Action recorded and server state refreshed.','سجل الإجراء وحدّثت الحالة من الخادم.','İşlem kaydedildi ve sunucu durumu yenilendi.'));}catch(error){if(alive.current)setActionError(visibleError(error));}finally{if(alive.current)setBusy(false);}};
 const inspectionValid=(row:RecordRow)=>{const day=row.created_at.slice(0,10),measured=Number(row.data.measured),nominal=Number(row.data.nominal),tolerance=Number(row.data.tolerance);return Boolean(actionLot&&Number(actionLot.good)>0&&Number(row.data.defects)===0&&row.created_at>=actionLot.createdAt&&row.updated_at>=actionLot.updatedAt&&[measured,nominal,tolerance].every(Number.isFinite)&&tolerance>=0&&Math.abs(measured-nominal)<=tolerance&&approved('calibration').some(calibration=>calibration.data.instrument===row.data.instrument&&String(calibration.data.calibratedAt)<=day&&String(calibration.data.expiresAt)>=day&&String(calibration.data.calibratedAt)<=today&&String(calibration.data.expiresAt)>=today));};
