 {tab==='tasks'&&<><thead><tr>{[w('پرونده و حوزه','Record and domain','السجل والمجال','Kayıt ve alan'),w('مسئول و موعد','Owner and due date','المسؤول والموعد','Sorumlu ve vade'),w('وضعیت و اقدام','State and action','الحالة والإجراء','Durum ve işlem')].map(title=><th key={title}>{title}</th>)}</tr></thead><tbody>{snapshot.tasks.map(task=><tr key={task.id} className={selection?.id===task.id?'selected':''}><td><button type="button" className="exec-row-link exec-code" onClick={()=>choose('task',task.id)}>{taskTitle(task)}</button><small>{task.kind==='maintenance'?w('نگهداری تجهیز','Equipment maintenance','صيانة المعدات','Ekipman bakımı'):w('اقدام اصلاحی کیفیت','Quality corrective action','إجراء تصحيحي للجودة','Kalite düzeltici faaliyeti')}</small></td><td>{ownerName(task.ownerId)}<small>{dateText(task.dueDate)}</small>{task.status!=='closed'&&task.dueDate<today&&<small>{w('موعد گذشته','Overdue','متأخر','Gecikmiş')}</small>}</td><td><Badge value={task.status}/><div className="exec-inline-actions"><button type="button" onClick={()=>choose('task',task.id)}>{w('جزئیات','Details','التفاصيل','Ayrıntılar')}</button>{task.ownerId===user.id&&task.status==='open'&&rowAction('task',task.id,'start')}{task.ownerId===user.id&&task.status==='in_progress'&&rowAction('task',task.id,'complete')}{['admin',task.kind==='maintenance'?'maintenance':'quality'].includes(user.role)&&task.status==='verification'&&rowAction('task',task.id,'verify',task.ownerId===user.id)}{(task.kind==='maintenance'?permissions.assignMaintenance:permissions.assignCapa)&&['open','in_progress'].includes(task.status)&&rowAction('task',task.id,'assign')}{(task.kind==='maintenance'?permissions.assignMaintenance:permissions.assignCapa)&&task.status==='closed'&&rowAction('task',task.id,'reopen')}</div></td></tr>)}</tbody></>}
